package cn.haiduo.finance;
import cn.haiduo.audit.Audit;
import java.util.*;
import java.math.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
@Service public class ProfitConfirmations {
 private final JdbcTemplate db;public ProfitConfirmations(JdbcTemplate db){this.db=db;}
 @Transactional public Object confirm(UUID tenant,UUID order,UUID key,String source,String actor){if(key==null||source==null||source.isBlank()||source.length()>200)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"请填写实际费用核对凭据/说明");var orders=db.queryForList("select status,payment_status,refund_status,net,rate,currency from sales_order where tenant_id=? and id=? for update",tenant,order);if(orders.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);var previous=db.queryForList("select id,order_id,source from profit_confirmation where tenant_id=? and request_key=?",tenant,key);if(!previous.isEmpty()){var old=previous.getFirst();if(!old.get("order_id").equals(order)||!old.get("source").equals(source))throw new ResponseStatusException(HttpStatus.CONFLICT,"确认幂等键冲突");return Map.of("id",old.get("id"),"duplicate",true);}var o=orders.getFirst();if(!o.get("status").equals("SHIPPED")||!o.get("payment_status").equals("PAID")||!o.get("refund_status").equals("NONE"))throw new ResponseStatusException(HttpStatus.CONFLICT,"仅已付款、已发货且无退款订单可人工确认");var cost=db.queryForMap("select sum(quantity*unit_cost_cny) amount,count(*) filter(where unit_cost_cny is null) missing,count(*) items from order_item where tenant_id=? and order_id=?",tenant,order);var fees=db.queryForList("select kind,amount_cny from order_fee where tenant_id=? and order_id=? order by kind for update",tenant,order);if(((Number)cost.get("missing")).longValue()>0||((Number)cost.get("items")).longValue()==0||fees.size()!=2)throw new ResponseStatusException(HttpStatus.CONFLICT,"需完整采购快照及已核对的运费、平台费，实际为0也须录入");Map<String,BigDecimal> amounts=new HashMap<>();for(var f:fees)amounts.put((String)f.get("kind"),(BigDecimal)f.get("amount_cny"));BigDecimal purchase=(BigDecimal)cost.get("amount"),net=(BigDecimal)o.get("net"),rate=(BigDecimal)o.get("rate"),freight=amounts.get("FREIGHT"),platform=amounts.get("PLATFORM"),profit=net.multiply(rate).subtract(purchase).subtract(freight).subtract(platform).setScale(2,RoundingMode.HALF_UP);UUID id=UUID.randomUUID();int version=db.queryForObject("select coalesce(max(version),0)+1 from profit_confirmation where tenant_id=? and order_id=?",Integer.class,tenant,order);db.update("insert into profit_confirmation(id,tenant_id,order_id,request_key,version,net_original,currency,exchange_rate,purchase_cny,freight_cny,platform_cny,contribution_cny,source,actor) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id,tenant,order,key,version,net,o.get("currency"),rate,purchase,freight,platform,profit,source,actor);new Audit(db).record(tenant,actor,"PROFIT_CONFIRMED",id);return Map.of("id",id,"version",version,"contribution",profit.toPlainString(),"basis","MANUALLY_CONFIRMED_ACTUAL","duplicate",false);}
}
